(()=>{const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let dialog,data=null,customer='',company='NCT',pending=null,saving=false,timer=null,serial=0;
 function send(action,input){if(saving)return;pending={type:'SALES_ROOM_SHIPMENT_REQUEST',customerId:customer,company,action,requestId:crypto.randomUUID(),input:['SELECT','CANCEL','PLAN'].includes(action)&&data?.stockCurrent?JSON.parse(JSON.stringify({...input,stockCurrent:data.stockCurrent})):input};transmit();}
 function transmit(){saving=true;dialog.querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=true);window.parent.postMessage(pending,'*');const request=pending,attempt=++serial;clearTimeout(timer);timer=setTimeout(()=>{if(pending===request&&serial===attempt){saving=false;dialog.querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=false);dialog.querySelector('[data-status]').textContent='Save/read not confirmed 尚未确认，请重试同一次操作';dialog.querySelector('[data-retry]').hidden=false;}},30000);}
 function render(){dialog.innerHTML='<div class="dialog-header"><h2>Select Shipment 选择本次发货</h2><button data-close>×</button></div><div class="dialog-body"><label>Company 公司 <select data-company><option>NCT</option><option>GHR</option></select></label><p data-status role="status"></p><p>Only allocated cartons can be selected. 只可选择采购员已分配的数量。</p><table><thead><tr><th>Select</th><th>Barcode · Item</th><th>Available 可用</th><th>This Shipment 本次发货</th></tr></thead><tbody>'+(data?.lines||[]).filter(row=>row.available>0).map((row,index)=>'<tr data-task="'+esc(row.taskId)+'"><td><input data-select type="checkbox" aria-label="Select '+esc(row.barcode)+'"></td><td>'+esc(row.barcode)+'<br><b>'+esc(row.name)+'</b><small>'+esc(row.packing)+'</small></td><td>'+row.available+'</td><td><input data-qty type="number" min="1" max="'+row.available+'" value="'+row.available+'" aria-label="Shipment quantity '+esc(row.barcode)+'"></td></tr>').join('')+'</tbody></table><label>Instructions 发货说明<textarea data-reason rows="2" maxlength="2000"></textarea></label><button data-save>Send to Support 交给文员开票</button><h3>Shipment Requests 发货申请</h3>'+(data?.shipments||[]).map(row=>'<div class="shipment-record"><b>'+esc(row.invoice?.number||row.requestedAt)+' · '+esc({REQUESTED:'Awaiting Support 等待开票',INVOICED:'Invoiced 已开票',DISPATCHED:'Dispatched 已发货',CANCELLED:'Cancelled 已取消'}[row.status])+'</b><small>'+row.lines.reduce((n,line)=>n+line.quantity,0)+' CTN · '+esc(row.requestedBy)+'</small>'+(row.status==='REQUESTED'?'<button data-cancel="'+esc(row.id)+'">Withdraw 撤回</button>':'')+'</div>').join('')+'<button data-retry hidden>Retry 重试</button></div>';dialog.querySelector('[data-company]').value=company;
 dialog.querySelector('[data-close]').onclick=()=>{if(!saving&&!pending)dialog.close();};dialog.querySelector('[data-company]').onchange=event=>{if(pending)return;company=event.target.value;data=null;render();send('READ');};dialog.querySelector('[data-retry]').onclick=()=>{if(pending&&!saving)transmit();};
 dialog.querySelector('[data-save]').onclick=()=>{if(!data||pending)return;const lines=[...dialog.querySelectorAll('[data-task]')].filter(el=>el.querySelector('[data-select]').checked).map(el=>({taskId:el.dataset.task,quantity:Number(el.querySelector('[data-qty]').value)})),reason=dialog.querySelector('[data-reason]').value.trim();if(!lines.length||!reason){dialog.querySelector('[data-status]').textContent='Select lines and enter instructions 请勾选产品并填写说明';return;}send('SELECT',{version:data.version,customerId:customer,lines,reason});};
 dialog.querySelectorAll('[data-cancel]').forEach(button=>button.onclick=()=>{const reason=dialog.querySelector('[data-reason]').value.trim();if(!reason){dialog.querySelector('[data-status]').textContent='Enter withdrawal reason 请填写撤回原因';return;}send('CANCEL',{id:button.dataset.cancel,version:data.version,reason});});
 }
 function renderSplitPlan(){
  if(!data)return;
  const section=document.createElement('details');section.className='split-shipment-plan';
  section.innerHTML='<summary>Split Shipment 分批发货计划</summary><p>Plan customer quantities before goods arrive. Actual invoicing uses confirmed available stock. 可先安排客户要求的批次；实际开票以确认可发数量为准。</p><table><thead><tr><th>Select</th><th>Barcode · Item</th><th>Requested 需求</th><th>Batch 1 第一批</th><th>Batch 2 第二批</th></tr></thead><tbody>'+data.lines.map(row=>'<tr data-plan-task="'+esc(row.taskId)+'"><td><input data-plan-select type="checkbox"></td><td>'+esc(row.barcode)+'<br>'+esc(row.name)+'</td><td>'+row.requested+'</td><td><input data-first type="number" min="1" max="'+row.requested+'" value="'+Math.ceil(row.requested/2)+'"></td><td><input data-second type="number" min="1" max="'+row.requested+'" value="'+Math.floor(row.requested/2)+'"></td></tr>').join('')+'</tbody></table><label>Reason 分批原因<textarea data-plan-reason rows="2" maxlength="2000"></textarea></label><button data-plan-save>Save Plan 保存计划</button><div>'+data.plans.map(plan=>'<p>'+esc(plan.orderId)+' · '+plan.batches.map(batch=>esc(batch.label)+': '+batch.lines.reduce((sum,line)=>sum+line.quantity,0)+' CTN').join(' | ')+'<small>'+esc(plan.at)+' · by '+esc(plan.by)+'</small></p>').join('')+'</div>';
  for(const row of section.querySelectorAll('[data-plan-task]')){const prior=data.plans.find(plan=>plan.batches.some(batch=>batch.lines.some(line=>line.taskId===row.dataset.planTask)));if(prior&&prior.batches.length===2){row.querySelector('[data-first]').value=prior.batches[0].lines.find(line=>line.taskId===row.dataset.planTask)?.quantity||0;row.querySelector('[data-second]').value=prior.batches[1].lines.find(line=>line.taskId===row.dataset.planTask)?.quantity||0;}}
  dialog.querySelector('[data-status]').after(section);
  section.querySelector('[data-plan-save]').onclick=()=>{
   if(pending)return;
   const chosen=[...section.querySelectorAll('[data-plan-task]')].filter(row=>row.querySelector('[data-plan-select]').checked),reason=section.querySelector('[data-plan-reason]').value.trim(),orders=new Set(chosen.map(row=>data.lines.find(line=>line.taskId===row.dataset.planTask).orderId));
   if(!chosen.length||orders.size!==1||!reason){dialog.querySelector('[data-status]').textContent='Select lines from one order and enter the split reason 请选同一订单的产品并填写分批原因';return;}
   const batches=['first','second'].map((key,index)=>({label:'Shipment '+(index+1),lines:chosen.map(row=>({taskId:row.dataset.planTask,quantity:Number(row.querySelector('[data-'+key+']').value)}))}));
   if(chosen.some((row,index)=>batches.some(batch=>!Number.isSafeInteger(batch.lines[index].quantity)||batch.lines[index].quantity<1)||batches.reduce((sum,batch)=>sum+batch.lines[index].quantity,0)!==data.lines.find(line=>line.taskId===row.dataset.planTask).requested)){dialog.querySelector('[data-status]').textContent='Both batches must total the original quantity 两批数量合计必须等于客户原始需求';return;}
   send('PLAN',{version:data.planVersion,customerId:customer,orderId:[...orders][0],batches,reason});
  };
 }
 window.addEventListener('beforeunload',event=>{if(pending?.input?.stockCurrent){event.preventDefault();event.returnValue='';}});
 window.masterShipments={open(customerId){if(pending?.input?.stockCurrent){if(!dialog.open)dialog.showModal();return;}if(!dialog){dialog=document.createElement('dialog');dialog.className='master-shipment-dialog';document.body.appendChild(dialog);dialog.addEventListener('cancel',event=>{if(saving||pending)event.preventDefault();});}customer=customerId;data=null;pending=null;render();dialog.showModal();send('READ');}};
 window.addEventListener('message',event=>{const message=event.data;if(event.source!==window.parent||message?.type!=='SALES_ROOM_SHIPMENT_RESULT'||message.requestId!==pending?.requestId||message.company!==company)return;clearTimeout(timer);serial++;saving=false;dialog.querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=false);if(!message.ok){dialog.querySelector('[data-status]').textContent=message.error||'Request failed 请求未确认';if(!pending.input?.stockCurrent&&/changed|Enter|Select|exceeds|already exists|not authorized/.test(message.error||''))pending=null;else dialog.querySelector('[data-retry]').hidden=false;return;}if(pending.action==='READ'&&message.result?.stockCurrent!=null){const meta=message.result.stockCurrent;if(meta.schema!=='CURRENT_STOCK_V2'||meta.stockProtocol!==1||typeof meta.stockBuild!=='string'||!meta.stockBuild||!Number.isSafeInteger(meta.stockGeneration)||meta.stockGeneration<0){dialog.querySelector('[data-status]').textContent='Current shipment form unavailable 请刷新后重试';dialog.querySelector('[data-retry]').hidden=false;return;}}if(pending.input?.stockCurrent){const receipt=message.result;if(receipt?.ok===false&&receipt.pending===true&&receipt.requestId===pending.requestId&&['BEFORE','APPLY','VERIFY'].includes(receipt.phase)&&Number.isSafeInteger(receipt.completedCount)&&Number.isSafeInteger(receipt.totalRecords)&&receipt.totalRecords>0&&receipt.completedCount>=0&&receipt.completedCount<=receipt.totalRecords){saving=true;dialog.querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=true);dialog.querySelector('[data-status]').textContent='Saving 保存中… '+receipt.completedCount+' / '+receipt.totalRecords;timer=setTimeout(transmit,250);return;}if(receipt?.ok!==true||receipt.requestId!==pending.requestId||!Number.isSafeInteger(receipt.stockGeneration)||receipt.stockGeneration<=pending.input.stockCurrent.stockGeneration){dialog.querySelector('[data-status]').textContent='Save not confirmed 保存尚未确认，请重试同一次操作';dialog.querySelector('[data-retry]').hidden=false;return;}}const action=pending.action;pending=null;if(action==='READ'){data=message.result;render();renderSplitPlan();}else send('READ');});
})();
